package me.matsumo.fanbox.core.logs.category

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

// This class is automatically generated by generate-log-classes.
sealed interface OffersLog : LogCategory {

    class BannerShown internal constructor(offerType: String, offerCycle: Int) : OffersLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "offers")
            put("event_name", "banner_shown")
            put("offer_type", offerType)
            put("offer_cycle", offerCycle)
        }
    }

    class BannerTapped internal constructor(offerType: String, offerCycle: Int) : OffersLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "offers")
            put("event_name", "banner_tapped")
            put("offer_type", offerType)
            put("offer_cycle", offerCycle)
        }
    }

    class BannerDismissed internal constructor(offerType: String, offerCycle: Int) : OffersLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "offers")
            put("event_name", "banner_dismissed")
            put("offer_type", offerType)
            put("offer_cycle", offerCycle)
        }
    }

    companion object {
        // オファーのバナーを表示したときのログ。ホーム画面の表示中は、オファーの種類と周期の組ごとに 1 回だけ送る
        fun bannerShown(offerType: String, offerCycle: Int) = BannerShown(offerType, offerCycle)

        // オファーのバナーを押し、課金画面を開いたときのログ。課金画面のログの referrer は offer_banner になる
        fun bannerTapped(offerType: String, offerCycle: Int) = BannerTapped(offerType, offerCycle)

        // オファーのバナーを閉じたときのログ。閉じた周期の間は、バナーを表示しない
        fun bannerDismissed(offerType: String, offerCycle: Int) = BannerDismissed(offerType, offerCycle)
    }
}
